using System;
using Microsoft.AspNetCore.Http;

namespace QuickCode.Quickcode.Portal.Helpers.BlobStorage;

/// <summary>
/// Max upload sizes for Portal BLOB_* / IMAGE fields.
/// Image 5 MB, PDF 10 MB, video 20 MB; other files default to PDF limit.
/// </summary>
public static class BlobUploadLimits
{
    public const long ImageBytes = 5L * 1024 * 1024;
    public const long PdfBytes = 10L * 1024 * 1024;
    public const long VideoBytes = 20L * 1024 * 1024;
    public const long DefaultFileBytes = PdfBytes;

    /// <summary>Server multipart / Kestrel ceiling (must be &gt;= largest allowed upload).</summary>
    public const long RequestBodyBytes = VideoBytes;

    public static long GetMaxBytes(string? contentType)
    {
        var ct = (contentType ?? string.Empty).Trim().ToLowerInvariant();
        if (ct.StartsWith("image/", StringComparison.Ordinal))
            return ImageBytes;
        if (ct.Contains("pdf", StringComparison.Ordinal) || ct == "application/pdf")
            return PdfBytes;
        if (ct.StartsWith("video/", StringComparison.Ordinal))
            return VideoBytes;
        return DefaultFileBytes;
    }

    public static string FormatMb(long bytes) => $"{bytes / (1024 * 1024)} MB";

    public static bool TryValidate(IFormFile file, out string? error)
    {
        error = null;
        if (file == null || file.Length <= 0)
            return true;

        var max = GetMaxBytes(file.ContentType);
        if (file.Length <= max)
            return true;

        error = $"File '{file.FileName}' is too large ({FormatMb(file.Length)}). Maximum allowed is {FormatMb(max)}.";
        return false;
    }
}
